'use strict';
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const KEY='blockbuster-game-v1', PREF='blockbuster-settings-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key){try{return JSON.parse(localStorage.getItem(key));}catch{return null;}}
function write(key,val){try{localStorage.setItem(key,JSON.stringify(val));}catch{}}
function erase(key){try{localStorage.removeItem(key);}catch{}}
const defaults={level:'Todas',category:'Todas',seconds:45,rounds:3,mode:'Jugadores',sound:true};
let prefs={...defaults,...read(PREF)},names=['Jugador 1','Jugador 2'],view='home',engine=new GameEngine(MOVIES),saved=read(KEY),audioCtx,installPrompt,toastTimer;
if(!saved||saved.version!==1||!Array.isArray(saved.players)||!Array.isArray(saved.deck)||!saved.deck.length||saved.deck.some(id=>!MOVIES.some(m=>m.id===id))){saved=null;erase(KEY);}
if(saved?.status==='playing'){saved.status='paused';saved.deadline=null;}
function save(){saved=engine.s;write(KEY,saved);}
function persistPrefs(){write(PREF,prefs);}
function notify(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500);}
function sound(type){if(!prefs.sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const t=audioCtx.currentTime;const tones=type==='correct'?[523,659,784]:type==='end'?[260,200]:[440];tones.forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.value=f;g.gain.setValueAtTime(.055,t+i*.11);g.gain.exponentialRampToValueAtTime(.001,t+i*.11+.15);o.start(t+i*.11);o.stop(t+i*.11+.16);});}catch{}}
function header(){const playing=view==='game'&&engine.s?.status==='playing';return `<div class="topbar"><button class="brand" data-action="home" aria-label="Blockbuster, inicio"><img class="game-wordmark" src="../../assets/blockbuster-logo.png" alt="Blockbuster" width="2048" height="682"></button><nav class="nav">${playing?'<button class="iconbutton" data-action="pause" aria-label="Pausar partida">Ⅱ</button>':'<button class="ghost" data-action="rules">Cómo jugar <span aria-hidden="true">↗</span></button>'}<button class="iconbutton" data-action="sound" aria-label="${prefs.sound?'Silenciar':'Activar'} sonidos" aria-pressed="${prefs.sound}">${prefs.sound?'♪':'♫̸'}</button></nav></div>`;}
function home(){return `${saved&&saved.status!=='over'?'<div class="resume-banner"><span>Tienes una noche de cine pendiente.</span><button data-action="resumeSaved">Continuar →</button></div>':''}<section class="hero"><div><div class="eyebrow">ESTA NOCHE, EL CINE LO PONES TÚ</div><h1>Te sabes<br>la película.<br><em>¿O no?</em></h1><p class="intro">Cinco pistas. Una respuesta. Reúne a tu gente y descubre quién se lleva todos los créditos.</p><button class="primary" data-action="setup">Empezar partida <span aria-hidden="true">▶</span></button><p class="fine">2+ JUGADORES · UN SOLO DISPOSITIVO · 5–15 MIN</p></div><div class="tape-scene" aria-hidden="true"><div class="orbit"></div><div class="tape"><div class="tape-label"><div class="eyebrow">SECCIÓN: NOCHES INOLVIDABLES</div><h2>BLOCKBUSTER</h2><div class="label-bottom"><span>CINCO PISTAS</span><span>PLAY ▷ &nbsp; VOL. 01</span></div></div><div class="tape-window"><div class="reel"></div><div class="tape-line"></div><div class="reel"></div></div><div class="vhs">VHS ▰</div></div><div class="ticket"><span>TU MEJOR PAPEL</span><strong>5 PISTAS</strong><span>¿CUÁNTAS NECESITAS?</span></div></div></section><section class="features"><div class="feature"><span class="num">01 /</span><div><strong>Lee. Adivina. Celebra.</strong><p>Una persona lee, la otra encuentra la película.</p></div></div><div class="feature"><span class="num">02 /</span><div><strong>Menos pistas, más puntos.</strong><p>De 5 a 1 punto. Cada ayuda tiene su precio.</p></div></div><div class="feature"><span class="num">03 /</span><div><strong>Hay cine para todos.</strong><p>${MOVIES.length} películas, tres niveles y muchas historias.</p></div></div></section><footer class="footer"><span>CREADO POR BUKLABS · QUE EMPIECE LA FUNCIÓN.</span><button class="ghost install" data-action="install">Añadir a pantalla de inicio ↗</button></footer>`;}
function choices(key,items){return `<div class="segments">${items.map(([val,label])=>`<button class="chip ${String(prefs[key])===String(val)?'active':''}" data-action="setting" data-key="${key}" data-value="${val}" aria-pressed="${String(prefs[key])===String(val)}">${label}</button>`).join('')}</div>`;}
function pool(){return MOVIES.filter(m=>(prefs.level==='Todas'||m.level===prefs.level)&&(prefs.category==='Todas'||m.category===prefs.category));}
function setup(){return `<section class="screen"><div class="eyebrow">PREPARA LAS CABRITAS</div><h1>Arma tu función.</h1><p class="sub">Elige quién juega y qué tan cinéfilos se sienten hoy.</p><div class="setup-grid"><section class="panel"><h2>01 &nbsp; El reparto</h2>${choices('mode',[['Jugadores','Por jugador'],['Equipos','Por equipo']])}<p class="note">${prefs.mode==='Equipos'?'Agrega los equipos. En cada turno, alguien de otro equipo lee las pistas.':'Agrega a quienes adivinan. El siguiente jugador será quien lea las pistas.'}</p><form id="add-form" class="add-row"><input id="name-input" maxlength="35" placeholder="${prefs.mode==='Equipos'?'Nombre del equipo':'Nombre del jugador'}" aria-label="Nombre del participante" autocomplete="off"><button class="secondary" type="submit" aria-label="Agregar participante">+</button></form><ul class="players">${names.map((n,i)=>`<li><b>${String(i+1).padStart(2,'0')}</b><span>${esc(n)}</span><button class="remove" data-action="remove" data-index="${i}" aria-label="Eliminar ${esc(n)}">×</button></li>`).join('')}</ul><p class="note">Mínimo 2. Agrega tantos como quieras.</p></section><section class="panel"><h2>02 &nbsp; La cartelera</h2><span class="label">Dificultad</span>${choices('level',[['Todas','Mezcladas'],['Fácil','Fácil'],['Medio','Medio'],['Difícil','Difícil']])}<label class="label" for="category">Categoría</label><select id="category"><option value="Todas">Todas las categorías</option>${[...new Set(MOVIES.map(m=>m.category))].sort().map(c=>`<option ${prefs.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><span class="label">Tiempo por película</span>${choices('seconds',[[30,'30 s'],[45,'45 s'],[60,'60 s'],[0,'Sin reloj']])}<span class="label">Películas por ${prefs.mode==='Equipos'?'equipo':'jugador'}</span>${choices('rounds',[[1,'1'],[3,'3'],[5,'5'],[10,'10']])}</section></div><div class="start-row"><div><p class="note"><b>${pool().length} películas</b> en tu selección · ${names.length*prefs.rounds} turnos</p><p class="error" id="setup-error">${pool().length?'':'No hay películas con esta combinación. Cambia el nivel o la categoría.'}</p></div><button class="primary" data-action="create" ${names.length<2||!pool().length?'disabled':''}>¡Que empiece! <span>▶</span></button></div></section>`;}
function chips(){return `<div class="score-chips">${engine.s.players.map(p=>`<span>${esc(p.name)} <b>${p.score}</b></span>`).join('')}</div>`;}
function ready(){const s=engine.s,reader=s.players[(s.turn+1)%s.players.length].name;return `<section class="turn-card"><div class="disc" aria-hidden="true">▷</div><div class="eyebrow">RONDA ${engine.round} DE ${s.config.rounds}</div><p class="sub">Ahora adivina</p><h1>${esc(engine.player.name)}</h1><p class="sub">Pasa el dispositivo a <strong>${esc(reader)}</strong>${s.config.mode==='Equipos'?' para que alguien de ese equipo lea las pistas':''}.</p><p class="note">Quien adivina no debe mirar la pantalla.<br>${s.config.seconds?s.config.seconds+' segundos':'Sin límite de tiempo'} · hasta 5 puntos</p><button class="primary" data-action="begin">Estoy listo para leer <span>▶</span></button>${chips()}</section>`;}
function play(){const s=engine.s,m=engine.movie;return `<section class="game"><div class="game-meta"><span>${esc(engine.player.name)} · RONDA ${engine.round}/${s.config.rounds}</span><span class="timer" id="timer">${s.config.seconds?Math.ceil(s.remaining/1000)+'s':'∞'}</span></div><div class="time-track"><i id="timebar" style="width:${s.config.seconds?s.remaining/(s.config.seconds*10):100}%"></i></div><div class="movie-head"><div><div class="eyebrow">RESPUESTA · SOLO PARA QUIEN LEE</div><h1>${esc(m.title)}</h1></div><div class="points" aria-label="${engine.points} puntos disponibles"><b>${engine.points}</b><small>PUNTOS</small></div></div><div class="clues">${m.clues.map((c,i)=>i<s.revealed?`<div class="clue revealed ${i===s.revealed-1?'latest':''}"><span class="clue-num">0${i+1}</span><span>${esc(c)}</span></div>`:`<button class="clue locked ${i===s.revealed?'next':''}" data-action="reveal" ${i===s.revealed?'':'disabled'} aria-label="${i===s.revealed?'Revelar':'Bloqueada'} pista ${i+1}"><span class="clue-num">0${i+1}</span><span>${i===s.revealed?'Revelar siguiente pista':'Pista bloqueada'}</span><span class="lock">${i===s.revealed?'−1 PT →':'○'}</span></button>`).join('')}</div><div class="actions"><button class="secondary" data-action="wrong">Falló ${s.revealed<5?'→ otra pista':''}</button><button class="primary" data-action="correct">¡Acertó! &nbsp; +${engine.points}</button></div><div class="game-bottom"><button class="ghost" data-action="skip">Pasar película · 0 pts</button><span class="fine">PISTA ${s.revealed} / 5</span></div></section>`;}
function paused(){return `<section class="turn-card"><div class="disc">Ⅱ</div><div class="eyebrow">LA FUNCIÓN ESTÁ EN PAUSA</div><h1>Sin spoilers.</h1><p class="sub">El tiempo está detenido y las pistas, ocultas.<br>Devuelve el dispositivo a quien está leyendo.</p><button class="primary" data-action="unpause">Continuar película <span>▶</span></button><button class="ghost" data-action="home" style="margin-top:18px">Guardar y volver al inicio</button></section>`;}
function result(){const h=engine.s.history.at(-1),last=engine.s.turn+1>=engine.s.players.length*engine.s.config.rounds;return `<section class="turn-card"><div class="result-tag">${h.reason==='correct'?'¡ESO ES CINE!':h.reason==='timeout'?'SE ACABÓ EL TIEMPO':h.reason==='skip'?'OTRA SERÁ':'SE ACABARON LAS PISTAS'}</div><div class="earned">+${h.points}</div><div class="fine">PUNTOS PARA ${esc(h.player).toUpperCase()}</div><p class="result-title">${esc(h.title)}</p><p class="note">${h.reason==='correct'?`La adivinaste con ${h.clues} ${h.clues===1?'pista':'pistas'}.`:'La próxima película puede ser la tuya.'}</p><button class="primary" data-action="next">${last?'Ver resultados':'Siguiente turno'} <span>→</span></button>${chips()}</section>`;}
function over(){const sorted=[...engine.s.players].sort((a,b)=>b.score-a.score),winners=sorted.filter(p=>p.score===sorted[0].score);return `<section class="results"><div class="eyebrow">FIN DE LA FUNCIÓN</div><h1>${winners.length>1?'Un final compartido.':'El papel estelar es tuyo.'}</h1><p class="sub">${winners.length>1?'Empate entre '+winners.map(p=>esc(p.name)).join(', '):esc(winners[0].name)+' se lleva todos los aplausos.'}</p><ol class="podium">${sorted.map((p,i)=>`<li><span class="rank">${i===0?'★':i+1}</span><span class="name">${esc(p.name)}</span><span class="score">${p.score} <small>PTS</small></span></li>`).join('')}</ol><div class="buttons"><button class="primary" data-action="rematch">Otra función ↻</button><button class="secondary" data-action="edit">Cambiar jugadores</button></div><details class="history"><summary>Ver las ${engine.s.history.length} películas de la partida</summary>${engine.s.history.map(h=>`<p><span>${esc(h.player)} · ${esc(h.title)}</span><b>+${h.points} pts</b></p>`).join('')}</details></section>`;}
function render(){document.body.classList.toggle('playing',view==='game');let html=view==='home'?home():view==='setup'?setup():engine.s.status==='ready'?ready():engine.s.status==='playing'?play():engine.s.status==='paused'?paused():engine.s.status==='result'?result():over();app.innerHTML=`<main class="wrap">${header()}${html}</main>`;}
function openModal(html){modal.innerHTML=html;modal.showModal();}
function rules(){openModal(`<h2>Cinco pistas.<br>Una película.</h2><div class="rule"><b>01</b><p>Quien lee ve la respuesta. Quien adivina debe mirar hacia otro lado.</p></div><div class="rule"><b>02</b><p>Lee la primera pista. Si necesita ayuda, toca la siguiente para revelarla. Cada pista reduce un punto.</p></div><div class="kbd-score"><span>1ª → 5 pts</span><span>3ª → 3 pts</span><span>5ª → 1 pt</span></div><div class="rule"><b>03</b><p>Un intento por pista. Si responde mal, pulsa <strong>Falló</strong> para revelar la siguiente. En la quinta, el error termina el turno.</p></div><div class="rule"><b>04</b><p>Acepten títulos equivalentes: español, inglés o variantes de doblaje. Pulsa <strong>Acertó</strong> y los puntos se suman a quien adivina.</p></div><p>Las cartas no se repiten hasta agotar la selección. El juego se pausa al ocultar la página. Gana quien sume más al terminar todas las rondas.</p><button class="primary" data-action="close">Entendido, vamos al cine</button>`);}
function create(){try{engine=new GameEngine(MOVIES);engine.create(names,prefs);save();view='game';render();window.scrollTo(0,0);}catch(e){notify(e.message);}}
function toHome(){if(engine.s?.status==='playing')engine.pause();if(engine.s)save();view='home';render();window.scrollTo(0,0);}
function handle(action,el){
 switch(action){
 case 'home':toHome();break;
 case 'rules':rules();break;
 case 'close':modal.close();break;
 case 'sound':prefs.sound=!prefs.sound;persistPrefs();render();notify(prefs.sound?'Sonido activado':'Sonido silenciado');break;
 case 'setup':if(saved&&saved.status!=='over')openModal('<h2>¿Una nueva función?</h2><p>Hay una partida guardada. Puedes continuarla o reemplazarla al empezar la nueva.</p><button class="primary" data-action="resumeSaved">Continuar partida</button><button class="secondary" data-action="freshSetup">Preparar otra partida</button>');else{view='setup';render();window.scrollTo(0,0);}break;
 case 'freshSetup':modal.close();view='setup';render();window.scrollTo(0,0);break;
 case 'resumeSaved':modal.close();if(saved){engine=new GameEngine(MOVIES,saved);view='game';render();window.scrollTo(0,0);}break;
 case 'setting':{const key=el.dataset.key,val=el.dataset.value;if(key==='mode'&&val!==prefs.mode){const old=prefs.mode==='Equipos'?'Equipo':'Jugador',next=val==='Equipos'?'Equipo':'Jugador';names=names.map((n,i)=>n===`${old} ${i+1}`?`${next} ${i+1}`:n);}prefs[key]=['seconds','rounds'].includes(key)?Number(val):val;persistPrefs();render();break;}
 case 'remove':names.splice(Number(el.dataset.index),1);render();break;
 case 'create':create();break;
 case 'begin':if(engine.start()){sound('start');save();render();window.scrollTo(0,0);}break;
 case 'reveal':if(engine.reveal()){sound('start');}save();render();break;
 case 'correct':if(engine.correct())sound('correct');else if(engine.s.status==='result')sound('end');save();render();break;
 case 'wrong':engine.wrong();if(engine.s.status==='playing')notify('Otra pista. Un punto menos en juego.');else sound('end');save();render();break;
 case 'skip':engine.skip();save();render();break;
 case 'pause':engine.pause();save();render();break;
 case 'unpause':engine.resume();save();render();break;
 case 'next':engine.next();save();render();window.scrollTo(0,0);break;
 case 'rematch':names=engine.s.players.map(p=>p.name);prefs={...prefs,...engine.s.config};create();break;
 case 'edit':names=engine.s.players.map(p=>p.name);prefs={...prefs,...engine.s.config};view='setup';render();break;
 case 'install':window.BUK.install();break;
 }
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)handle(b.dataset.action,b);});
document.addEventListener('submit',e=>{if(e.target.id!=='add-form')return;e.preventDefault();const val=$('#name-input').value.trim();if(!val){notify('Escribe un nombre para agregarlo.');return;}if(names.some(n=>n.toLocaleLowerCase()===val.toLocaleLowerCase())){notify('Ese nombre ya está en el reparto.');return;}names.push(val);render();$('#name-input').focus();});
document.addEventListener('change',e=>{if(e.target.id==='category'){prefs.category=e.target.value;persistPrefs();render();}});
let lastSecond;
setInterval(()=>{if(view!=='game'||engine.s?.status!=='playing')return;const ended=engine.tick();if(ended){sound('end');save();render();return;}const s=engine.s,sec=Math.ceil(s.remaining/1000);const timer=$('#timer');if(timer){timer.textContent=s.config.seconds?`${sec}s`:'∞';timer.classList.toggle('urgent',!!s.config.seconds&&sec<=10);}const bar=$('#timebar');if(bar)bar.style.width=(s.config.seconds?s.remaining/(s.config.seconds*10):100)+'%';if(sec!==lastSecond){lastSecond=sec;save();}},100);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&engine.s?.status==='playing'){engine.pause();save();render();}});
window.addEventListener('pagehide',()=>{if(engine.s?.status==='playing')engine.pause();if(engine.s)save();});


render();

window.addEventListener('pageshow',event=>{if(event.persisted)render();});
